
import pylibxc
import pytest
from pylibxc.example_densities import test_data


def test_gga_xc_vv10_N_2_zk():
    # Prepare the input
    inp = test_data["N"]

    # Get the functional
    feval = pylibxc.LibXCFunctional("gga_xc_vv10", 2)
    if not feval._have_exc:
        pytest.skip("build lacks the derivative order for zk")

    # Evaluate only up to the tested field's derivative order. Computing higher
    # orders than this test checks is wasteful and can trip a latent bug in an
    # order the test does not exercise (e.g. an fxc segfault under a vrho test).
    out = feval.compute(inp, do_exc=feval._have_exc, do_vxc=False, do_fxc=False, do_kxc=False, do_lxc=False)
    ns = pylibxc.array_backend.array_namespace(out["zk"])
    tgt = out["zk"].flatten()
    ref_tgt = ns.full_like(tgt, ns.asarray([-4.384386454946263e+00, -4.303729421575754e+00, -4.190941202275955e+00, -4.035165457220169e+00, -3.823801824547081e+00, -3.544127149494181e+00, -3.186674103587984e+00, -2.750066346676148e+00, -2.244835847172706e+00, -1.694254332987519e+00, -1.139721787953045e+00, -7.535455944597831e-01, -6.476957121979191e-01, -5.414408552548833e-01, -4.001090790044658e-01, -2.556991161426569e-01, -1.405525370122112e-01, -6.439417217064027e-02, -2.409551103157706e-02, -6.420109109574660e-03]))
    error = ns.max(ns.abs(tgt-ref_tgt))/(1.0+ns.max(ns.asarray([ns.abs(tgt), ns.abs(ref_tgt)])))
    assert error < 5e-08


